import json
from .session import ReviewSession
def build_reviewer_html(session:ReviewSession)->str:
    payload=json.dumps(session.project.model_dump(mode='json'),ensure_ascii=False).replace('</','<\\/')
    return '''<!doctype html><html><head><meta charset="utf-8"><title>CompatibilizaBIM Reviewer</title><style>body{font-family:system-ui;margin:0;display:grid;grid-template-columns:1fr 340px;height:100vh}#view{background:#111}aside{padding:14px;overflow:auto}canvas{width:100%;height:100%}button,input{margin:4px;padding:7px}.row{border-bottom:1px solid #ddd;padding:6px;cursor:pointer}</style></head><body><div id="view"><canvas id="c"></canvas></div><aside><h2>CAD/BIM Reviewer</h2><div id="stats"></div><button onclick="act('confirmed')">Confirmar</button><button onclick="act('rejected')">Rejeitar</button><button onclick="undo()">Undo</button><button onclick="redo()">Redo</button><button onclick="download()">Exportar CBIM</button><br><label>Nome <input id="name"></label><button onclick="editName()">Editar</button><div id="list"></div></aside><script>let project='''+payload+''',selected=null,undoStack=[],redoStack=[];const deep=x=>JSON.parse(JSON.stringify(x));function color(e){if(e.review_state==='rejected')return '#d33';if(e.review_state==='confirmed')return '#2b7';if(e.confidence>=.85)return '#49c';if(e.confidence>=.6)return '#db3';return '#e55'}function points(){let a=[];for(const e of project.elements){if(e.start)a.push(e.start,e.end);if(e.center)a.push(e.center);if(e.position)a.push(e.position);if(e.boundary)a.push(...e.boundary)}return a}function draw(){const c=document.getElementById('c'),r=c.getBoundingClientRect();c.width=r.width*devicePixelRatio;c.height=r.height*devicePixelRatio;let p=points();if(!p.length)return;let xs=p.map(q=>q.x),ys=p.map(q=>q.y),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys),s=Math.min(c.width/(maxx-minx+1),c.height/(maxy-miny+1))*.8,tx=c.width*.1-minx*s,ty=c.height*.9+miny*s,ctx=c.getContext('2d');ctx.lineWidth=3*devicePixelRatio;ctx.clearRect(0,0,c.width,c.height);const P=q=>[q.x*s+tx,ty-q.y*s];for(const e of project.elements){ctx.strokeStyle=color(e);ctx.fillStyle=color(e);if(e.start){let a=P(e.start),b=P(e.end);ctx.beginPath();ctx.moveTo(...a);ctx.lineTo(...b);ctx.stroke()}if(e.boundary){ctx.beginPath();e.boundary.forEach((q,i)=>{let v=P(q);i?ctx.lineTo(...v):ctx.moveTo(...v)});ctx.closePath();ctx.stroke()}if(e.position||e.center){let v=P(e.position||e.center);ctx.beginPath();ctx.arc(v[0],v[1],6*devicePixelRatio,0,Math.PI*2);ctx.fill()}}}function render(){document.getElementById('list').innerHTML=project.elements.map(e=>`<div class=row onclick="sel('${e.id}')"><b>${e.type}</b> ${e.name||''}<br><small>${e.id} · ${Math.round(e.confidence*100)}% · ${e.review_state}</small></div>`).join('');let s={};project.elements.forEach(e=>s[e.review_state]=(s[e.review_state]||0)+1);document.getElementById('stats').textContent=JSON.stringify(s);draw()}function snap(){undoStack.push(deep(project));redoStack=[]}function sel(id){selected=id;let e=project.elements.find(x=>x.id===id);document.getElementById('name').value=e.name||''}function act(state){if(!selected)return;snap();project.elements.find(x=>x.id===selected).review_state=state;render()}function editName(){if(!selected)return;snap();let e=project.elements.find(x=>x.id===selected);e.name=document.getElementById('name').value;e.review_state='edited';render()}function undo(){if(!undoStack.length)return;redoStack.push(deep(project));project=undoStack.pop();render()}function redo(){if(!redoStack.length)return;undoStack.push(deep(project));project=redoStack.pop();render()}function download(){let b=new Blob([JSON.stringify(project,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='reviewed.cbim.json';a.click()}window.onresize=draw;render();</script></body></html>'''
